533	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
534		if prev.Kind != "transfer" || prev.Params != sig {
535			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
536				ErrRequestConflict, prev.Operator, prev.RequestID)
537		}
538		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
539			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
540		if prev.Rejected {
541			res.Err = codeErr(prev.Reason)
542			return res, res.Err
543		}
544		return res, nil
545	}
