549	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
550	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
551	func authzCurrentStatus(a authzRec, now time.Time) string {
552		switch a.Status {
553		case "revoked":
554			return AuthRevoked
555		case "used":
556			return AuthUsed
557		}
558		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
559			return AuthExpired
560		}
561		return AuthActive
562	}
