602	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
603		b, _ := json.Marshal(struct {
604			Kind          string `json:"kind"`
605			AuthID        string `json:"auth_id"`
606			ItemID        string `json:"item_id"`
607			TrusteeID     string `json:"trustee_id"`
608			ToID          string `json:"to_id"`
609			ExpectedOwner string `json:"expected_owner"`
610			ExpectedVer   int64  `json:"expected_version"`
611			ExpiresAt     string `json:"expires_at"`
612			Reason        string `json:"reason"`
613		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
614			req.ExpectedOwner, req.ExpectedVer,
615			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Reason})
616		return string(b)
617	}
