619	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
620	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
621	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
622	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
623	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
624	//
625	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
626	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
627	// 参数错误与引用不存在不占用请求号。
628	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
629		if err := req.validatePresent(); err != nil {
630			return CreateAuthorizationResult{}, err
631		}
632		r.mu.Lock()
633		defer r.mu.Unlock()
634		if err := r.checkOpen(); err != nil {
635			return CreateAuthorizationResult{}, err
636		}
637	
638		now := r.now()
639		key := requestKey(req.Operator, req.RequestID)
640		sig := createAuthzParamsSig(req)
641		if prev, ok := r.state.Requests[key]; ok {
642			return r.replayCreateAuthz(prev, sig)
643		}
644	
645		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
646			if !isValidationErr(bizErr) {
647				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
648				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
649				r.state.Requests[key] = request{
650					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
651					Params: sig, Rejected: true, Reason: errCode(bizErr),
652					AuthID: req.AuthID, ItemID: req.ItemID,
653				}
654				_ = r.commit()
655			}
656			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
657		}
658	
659		h := r.state.Holdings[req.ItemID]
660		a := authzRec{
661			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
662			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
663			GrantVer: h.Version, CreatedAt: now,
664		}
665		r.state.Authzs[req.AuthID] = a
666		authSeq := r.state.NextAuthSeq + 1
667		r.state.NextAuthSeq = authSeq
668		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
669			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
670			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
671			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
672		})
673		r.state.Requests[key] = request{
674			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
675			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
676		}
677		if err := r.commit(); err != nil {
678			return CreateAuthorizationResult{}, err
679		}
680		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
681	}
682	
683	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
684		h, ok := r.state.Holdings[req.ItemID]
685		if !ok {
686			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
687				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
688			}
689			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
690		}
691		op, ok := r.state.Accounts[req.Operator]
692		if !ok {
693			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
694		}
695		trustee, ok := r.state.Accounts[req.TrusteeID]
696		if !ok {
697			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
698		}
699		to, ok := r.state.Accounts[req.ToID]
700		if !ok {
701			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
702		}
703		if req.TrusteeID == req.Operator {
704			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
705		}
706		if req.ToID == req.Operator {
707			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
708		}
709		if !op.Active {
710			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
711		}
712		if !trustee.Active {
713			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
714		}
715		if !to.Active {
716			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
717		}
718		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
719		if _, exists := r.state.Authzs[req.AuthID]; exists {
720			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
721		}
722		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
723		if !req.ExpiresAt.After(now) {
724			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
725				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
726		}
727		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
728			req.Operator != h.OwnerID {
729			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
730				ErrConflict, req.ItemID, h.OwnerID, h.Version)
731		}
732		return nil
733	}
