735	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
736		if prev.Kind != "auth_create" || prev.Params != sig {
737			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
738				ErrRequestConflict, prev.Operator, prev.RequestID)
739		}
740		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
741			Status: AuthActive, Replayed: true}
742		if prev.Rejected {
743			res.Err = codeErr(prev.Reason)
744			return res, res.Err
745		}
746		return res, nil
747	}
