749	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
750		b, _ := json.Marshal(struct {
751			Kind   string `json:"kind"`
752			AuthID string `json:"auth_id"`
753			Reason string `json:"reason"`
754		}{"auth_revoke", req.AuthID, req.Reason})
755		return string(b)
756	}
757	
758	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
759	// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
760	// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
761	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
762		missing := []string{}
763		if strings.TrimSpace(req.Operator) == "" {
764			missing = append(missing, "operator")
765		}
766		if strings.TrimSpace(req.Reason) == "" {
767			missing = append(missing, "reason")
768		}
769		if strings.TrimSpace(req.RequestID) == "" {
770			missing = append(missing, "request_id")
771		}
772		if strings.TrimSpace(req.AuthID) == "" {
773			missing = append(missing, "auth_id")
774		}
775		if len(missing) > 0 {
776			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
777				ErrInvalidArgument, strings.Join(missing, ", "))
778		}
779		r.mu.Lock()
780		defer r.mu.Unlock()
781		if err := r.checkOpen(); err != nil {
782			return RevokeAuthorizationResult{}, err
783		}
784	
785		now := r.now()
786		key := requestKey(req.Operator, req.RequestID)
787		sig := revokeAuthzParamsSig(req)
788		if prev, ok := r.state.Requests[key]; ok {
789			return r.replayRevokeAuthz(prev, sig)
790		}
791	
792		a, ok := r.state.Authzs[req.AuthID]
793		if !ok {
794			// 引用不存在不占用请求号。
795			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
796			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
797		}
798		if a.GranterID != req.Operator {
799			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
800				ErrForbidden, a.GranterID, req.AuthID)
801			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
802			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
803		}
804		switch authzCurrentStatus(a, now) {
805		case AuthUsed:
806			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
807			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
808			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
809		case AuthRevoked:
810			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
811			// 相同请求重放回放同一结果。
812			r.state.Requests[key] = request{
813				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
814				Params: sig, AuthID: req.AuthID,
815			}
816			if err := r.commit(); err != nil {
817				return RevokeAuthorizationResult{}, err
818			}
819			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
820		}
821	
822		from := AuthActive
823		if authzCurrentStatus(a, now) == AuthExpired {
824			from = AuthExpired
825		}
826		a.Status = "revoked"
827		a.RevokedAt = now
828		r.state.Authzs[req.AuthID] = a
829		authSeq := r.state.NextAuthSeq + 1
830		r.state.NextAuthSeq = authSeq
831		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
832			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
833			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
834			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
835		})
836		r.state.Requests[key] = request{
837			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
838			Params: sig, AuthID: req.AuthID,
839		}
840		if err := r.commit(); err != nil {
841			return RevokeAuthorizationResult{}, err
842		}
843		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
844	}
845	
846	// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
847	func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
848		r.state.Requests[key] = request{
849			Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
850			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
851		}
852		_ = r.commit()
853	}
