855	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
856		if prev.Kind != "auth_revoke" || prev.Params != sig {
857			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
858				ErrRequestConflict, prev.Operator, prev.RequestID)
859		}
860		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
861		if prev.Rejected {
862			res.Err = codeErr(prev.Reason)
863			res.Status = ""
864			return res, res.Err
865		}
866		return res, nil
867	}
