869	func proxyTransferParamsSig(req ProxyTransferRequest) string {
870		b, _ := json.Marshal(struct {
871			Kind   string `json:"kind"`
872			AuthID string `json:"auth_id"`
873			Reason string `json:"reason"`
874		}{"proxy_transfer", req.AuthID, req.Reason})
875		return string(b)
876	}
877	
878	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
879	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
880	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
881	// 操作者记为实际受托账户并可通过授权编号追溯。
882	//
883	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
884	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
885	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
886	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
887	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
888	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
889	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
890		missing := []string{}
891		if strings.TrimSpace(req.Operator) == "" {
892			missing = append(missing, "operator")
893		}
894		if strings.TrimSpace(req.Reason) == "" {
895			missing = append(missing, "reason")
896		}
897		if strings.TrimSpace(req.RequestID) == "" {
898			missing = append(missing, "request_id")
899		}
900		if strings.TrimSpace(req.AuthID) == "" {
901			missing = append(missing, "auth_id")
902		}
903		if len(missing) > 0 {
904			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
905				ErrInvalidArgument, strings.Join(missing, ", "))
906		}
907		r.mu.Lock()
908		defer r.mu.Unlock()
909		if err := r.checkOpen(); err != nil {
910			return ProxyTransferResult{}, err
911		}
912	
913		now := r.now()
914		key := requestKey(req.Operator, req.RequestID)
915		sig := proxyTransferParamsSig(req)
916		if prev, ok := r.state.Requests[key]; ok {
917			return r.replayProxyTransfer(prev, sig)
918		}
919	
920		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
921			if !isValidationErr(bizErr) {
922				r.state.Requests[key] = request{
923					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
924					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
925				}
926				_ = r.commit()
927			}
928			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
929		}
930	
931		a := r.state.Authzs[req.AuthID]
932		h := r.state.Holdings[a.ItemID]
933		seq := r.state.NextSeq + 1
934		r.state.NextSeq = seq
935		from := h.OwnerID
936		fromVer := h.Version
937		h.OwnerID = a.ToID
938		h.Version = fromVer + 1
939		r.state.Holdings[a.ItemID] = h
940		r.state.History = append(r.state.History, historyEntry{
941			Seq: seq, Kind: "transfer", ItemID: a.ItemID, Operator: req.Operator,
942			Reason: req.Reason, RequestID: req.RequestID,
943			FromID: from, ToID: a.ToID, FromVersion: fromVer, ToVersion: fromVer + 1,
944			AuthID: a.ID,
945		})
946		a.Status = "used"
947		a.UsedTxSeq = seq
948		a.UsedAt = now
949		r.state.Authzs[a.ID] = a
950		authSeq := r.state.NextAuthSeq + 1
951		r.state.NextAuthSeq = authSeq
952		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
953			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
954			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
955			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: seq, OccurredAt: now,
956		})
957		r.state.Requests[key] = request{
958			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
959			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: from, ToID: a.ToID,
960			Version: fromVer + 1, TxSeq: seq,
961		}
962		if err := r.commit(); err != nil {
963			return ProxyTransferResult{}, err
964		}
965		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: from,
966			ToID: a.ToID, Version: fromVer + 1, TxSeq: seq}, nil
967	}
968	
969	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
970		a, ok := r.state.Authzs[req.AuthID]
971		if !ok {
972			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
973		}
974		op, ok := r.state.Accounts[req.Operator]
975		if !ok {
976			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
977		}
978		granter, gOk := r.state.Accounts[a.GranterID]
979		to, tOk := r.state.Accounts[a.ToID]
980		if req.Operator != a.TrusteeID {
981			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
982				ErrForbidden, req.Operator, req.AuthID)
983		}
984		if !gOk {
985			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
986		}
987		if !tOk {
988			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
989		}
990		if !op.Active {
991			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
992		}
993		if !granter.Active {
994			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
995		}
996		if !to.Active {
997			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
998		}
999		switch authzCurrentStatus(a, now) {
1000		case AuthRevoked:
1001			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1002		case AuthExpired:
1003			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1004		case AuthUsed:
1005			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1006		}
1007		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1008		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1009		h, ok := r.state.Holdings[a.ItemID]
1010		if !ok {
1011			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1012		}
1013		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1014			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1015				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1016		}
1017		return nil
1018	}
1019	
1020	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1021		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1022			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1023				ErrRequestConflict, prev.Operator, prev.RequestID)
1024		}
1025		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1026			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1027		if prev.Rejected {
1028			res.Err = codeErr(prev.Reason)
1029			return res, res.Err
1030		}
1031		return res, nil
1032	}
1033	
1034	// ---- 授权查询 ----
1035	
1036	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1037	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1038	// 到期但尚未终结的授权返回 AuthExpired。
1039	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1040		r.mu.Lock()
1041		defer r.mu.Unlock()
1042		if err := r.checkOpen(); err != nil {
1043			return Authorization{}, err
1044		}
1045		a, ok := r.state.Authzs[authID]
1046		if !ok {
1047			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1048		}
1049		return Authorization{
1050			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1051			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer,
1052			Status:    authzCurrentStatus(a, r.now()),
1053			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1054			RevokedAt: a.RevokedAt,
1055		}, nil
1056	}
1057	
1058	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1059	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1060	// 不存在时返回包裹 ErrNotFound 的错误。
1061	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1062		r.mu.Lock()
1063		defer r.mu.Unlock()
1064		if err := r.checkOpen(); err != nil {
1065			return nil, err
1066		}
1067		if _, ok := r.state.Items[itemID]; !ok {
1068			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1069		}
1070		out := make([]AuthorizationEvent, 0)
1071		for _, e := range r.state.AuthEvents {
1072			if e.ItemID != itemID {
1073				continue
1074			}
1075			out = append(out, AuthorizationEvent{
1076				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1077				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1078				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1079				OccurredAt: e.OccurredAt,
1080			})
1081		}
1082		return out, nil
1083	}
1084	
1085	// ---- 查询 ----
1086	
1087	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1088	func (r *Registry) GetItem(id string) (Item, error) {
1089		r.mu.Lock()
1090		defer r.mu.Unlock()
1091		if err := r.checkOpen(); err != nil {
1092			return Item{}, err
1093		}
1094		it, ok := r.state.Items[id]
1095		if !ok {
1096			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1097		}
1098		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1099			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1100	}
1101	
1102	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1103	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1104		r.mu.Lock()
1105		defer r.mu.Unlock()
1106		if err := r.checkOpen(); err != nil {
1107			return Holding{}, err
1108		}
1109		h, ok := r.state.Holdings[itemID]
1110		if !ok {
1111			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1112		}
1113		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1114	}
1115	
1116	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1117	// ErrNotFound 的错误；停用账户仍可正常查询。
1118	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1119		r.mu.Lock()
1120		defer r.mu.Unlock()
1121		if err := r.checkOpen(); err != nil {
1122			return nil, err
1123		}
1124		if _, ok := r.state.Accounts[accountID]; !ok {
1125			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1126		}
1127		out := make([]Holding, 0)
1128		for _, h := range r.state.Holdings {
1129			if h.OwnerID == accountID {
1130				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1131			}
1132		}
1133		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1134		return out, nil
1135	}
1136	
1137	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1138	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1139	// 返回包裹 ErrNotFound 的错误。
1140	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1141		r.mu.Lock()
1142		defer r.mu.Unlock()
1143		if err := r.checkOpen(); err != nil {
1144			return nil, err
1145		}
1146		if _, ok := r.state.Items[itemID]; !ok {
1147			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1148		}
1149		out := make([]HistoryEntry, 0)
1150		for _, e := range r.state.History {
1151			if e.ItemID != itemID {
1152				continue
1153			}
1154			out = append(out, HistoryEntry{
1155				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1156				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1157				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1158			})
1159		}
1160		return out, nil
1161	}
1162	
1163	// ---- 幂等辅助 ----
1164	
1165	func requestKey(operator, requestID string) string {
1166		return operator + "\x00" + requestID
1167	}
1168	
1169	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1170	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1171	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1172	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1173	// 并回放。
1174	func isValidationErr(err error) bool {
1175		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1176	}
1177	
1178	var errCodes = map[error]string{
1179		ErrNotFound:             "not_found",
1180		ErrAlreadyExists:        "already_exists",
1181		ErrAccountInactive:      "account_inactive",
1182		ErrSeriesSealed:         "series_sealed",
1183		ErrConflict:             "conflict",
1184		ErrSameAccount:          "same_account",
1185		ErrForbidden:            "forbidden",
1186		ErrAuthorizationRevoked: "authorization_revoked",
1187		ErrAuthorizationExpired: "authorization_expired",
1188		ErrAuthorizationUsed:    "authorization_used",
1189	}
1190	
1191	var codeErrs = map[string]error{
1192		"not_found":             ErrNotFound,
1193		"already_exists":        ErrAlreadyExists,
1194		"account_inactive":      ErrAccountInactive,
1195		"series_sealed":         ErrSeriesSealed,
1196		"conflict":              ErrConflict,
1197		"same_account":          ErrSameAccount,
1198		"forbidden":             ErrForbidden,
1199		"authorization_revoked": ErrAuthorizationRevoked,
1200		"authorization_expired": ErrAuthorizationExpired,
1201		"authorization_used":    ErrAuthorizationUsed,
1202	}
1203	
1204	func errCode(err error) string {
1205		for sentinel, code := range errCodes {
1206			if errors.Is(err, sentinel) {
1207				return code
1208			}
1209		}
1210		return "rejected"
1211	}
1212	
1213	func codeErr(code string) error {
1214		if e, ok := codeErrs[code]; ok {
1215			return e
1216		}
1217		return errors.New("registry: 请求曾被拒绝")
1218	}
