1	package registry
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"syscall"
10		"time"
11	)
12	
13	// stateVersion 是快照格式的版本标记，未来不兼容变更时可据此识别。
14	const stateVersion = 1
15	
16	const (
17		dirMode  = 0o755
18		fileMode = 0o644
19	)
20	
21	// snapshot 是登记册的全量落盘结构。账户、系列、藏品、持有、历史、
22	// 授权、授权变更记录与请求结果都在同一个快照中，一次操作一次原子
23	// 替换，保证"藏品已换人就一定有对应历史"。
24	type snapshot struct {
25		Version  int                 `json:"version"`
26		Accounts map[string]account  `json:"accounts"`
27		Series   map[string]series   `json:"series"`
28		Items    map[string]item     `json:"items"`
29		Holdings map[string]holding  `json:"holdings"`
30		History  []historyEntry      `json:"history"`
31		Requests map[string]request  `json:"requests"`
32		Authzs   map[string]authzRec `json:"authzs,omitempty"`
33		// AuthEvents 是按藏品记录的授权变更（创建/撤销/使用），在藏品
34		// 历史之外单独编号，不影响既有历史序号。
35		AuthEvents  []authzEvent `json:"auth_events,omitempty"`
36		NextSeq     int64        `json:"next_seq"`
37		NextAuthSeq int64        `json:"next_auth_seq,omitempty"`
38	}
39	
40	type account struct {
41		ID       string `json:"id"`
42		Metadata string `json:"metadata"`
43		Active   bool   `json:"active"`
44	}
45	
46	type series struct {
47		ID        string `json:"id"`
48		CreatorID string `json:"creator_id"`
49		Metadata  string `json:"metadata"`
50		Sealed    bool   `json:"sealed"`
51	}
52	
53	type item struct {
54		ID         string `json:"id"`
55		SeriesID   string `json:"series_id"`
56		BatchNo    string `json:"batch_no"`
57		Metadata   string `json:"metadata"`
58		IssuedTxID int64  `json:"issued_tx_id"`
59	}
60	
61	type holding struct {
62		ItemID  string `json:"item_id"`
63		OwnerID string `json:"owner_id"`
64		Version int64  `json:"version"`
65	}
66	
67	type historyEntry struct {
68		Seq         int64  `json:"seq"`
69		Kind        string `json:"kind"`
70		ItemID      string `json:"item_id"`
71		Operator    string `json:"operator"`
72		Reason      string `json:"reason"`
73		RequestID   string `json:"request_id"`
74		FromID      string `json:"from_id"`
75		ToID        string `json:"to_id"`
76		FromVersion int64  `json:"from_version"`
77		ToVersion   int64  `json:"to_version"`
78		// AuthID 非空表示该转让是受托人凭授权完成的代转。
79		AuthID string `json:"auth_id,omitempty"`
80	}
81	
82	// authzRec 是一份限时一次性代转授权的落盘状态。授权在创建时绑定藏品
83	// 当时的持有版本（GrantVer）；持有关系后续无论怎样变化，授权都不会
84	// 恢复或改变。
85	type authzRec struct {
86		ID        string    `json:"id"`
87		ItemID    string    `json:"item_id"`
88		GranterID string    `json:"granter_id"`
89		TrusteeID string    `json:"trustee_id"`
90		ToID      string    `json:"to_id"`
91		ExpiresAt time.Time `json:"expires_at"`
92		GrantVer  int64     `json:"grant_ver"`
93		// Status 只记录非时间派生的终态："revoked" 或 "used"；为空表示
94		// 尚未终结，当前是否有效由到期时间实时判断。
95		Status    string    `json:"status,omitempty"`
96		UsedTxSeq int64     `json:"used_tx_seq,omitempty"`
97		UsedAt    time.Time `json:"used_at,omitempty"`
98		CreatedAt time.Time `json:"created_at"`
99		RevokedAt time.Time `json:"revoked_at,omitempty"`
100	}
101	
102	// authzEvent 是授权变更记录：创建、撤销、使用各一条。
103	type authzEvent struct {
104		Seq        int64     `json:"seq"`
105		AuthID     string    `json:"auth_id"`
106		ItemID     string    `json:"item_id"`
107		Kind       string    `json:"kind"` // "create" / "revoke" / "use"
108		Operator   string    `json:"operator"`
109		Reason     string    `json:"reason"`
110		RequestID  string    `json:"request_id"`
111		FromStatus string    `json:"from_status,omitempty"`
112		ToStatus   string    `json:"to_status"`
113		TxSeq      int64     `json:"tx_seq,omitempty"`
114		OccurredAt time.Time `json:"occurred_at"`
115	}
116	
117	// request 保存每个 (操作者, 请求号) 的首次结果，用于幂等回放。
118	// 同一操作者的请求号在发行、转让、授权创建/撤销与代转之间共用。
119	type request struct {
120		Operator  string `json:"operator"`
121		RequestID string `json:"request_id"`
122		Kind      string `json:"kind"` // "issue" / "transfer" / "auth_create" / "auth_revoke" / "proxy_transfer"
123		// 规范化后的业务参数签名。签名一致才回放；不一致报请求号冲突。
124		Params string `json:"params"`
125		// 业务拒绝也落盘：相同参数重提返回首次的拒绝。
126		Rejected bool   `json:"rejected"`
127		Reason   string `json:"reject_reason"` // 哨兵错误对应的稳定标识
128		// 成功结果。
129		ItemID  string `json:"item_id,omitempty"`
130		AuthID  string `json:"auth_id,omitempty"`
131		FromID  string `json:"from_id,omitempty"`
132		ToID    string `json:"to_id,omitempty"`
133		Version int64  `json:"version,omitempty"`
134		TxSeq   int64  `json:"tx_seq,omitempty"`
135	}
136	
137	func newSnapshot() *snapshot {
138		return &snapshot{
139			Version:  stateVersion,
140			Accounts: make(map[string]account),
141			Series:   make(map[string]series),
142			Items:    make(map[string]item),
143			Holdings: make(map[string]holding),
144			Requests: make(map[string]request),
145			Authzs:   make(map[string]authzRec),
146		}
147	}
148	
149	func (s *snapshot) validate() error {
150		if s.Version != stateVersion {
151			return fmt.Errorf("%w: 不支持的快照版本 %d", ErrCorrupt, s.Version)
152		}
153		if s.Accounts == nil || s.Series == nil || s.Items == nil ||
154			s.Holdings == nil || s.Requests == nil {
155			return fmt.Errorf("%w: 快照内容不完整", ErrCorrupt)
156		}
157		if s.NextSeq < int64(len(s.History)) {
158			return fmt.Errorf("%w: 历史序号不连续", ErrCorrupt)
159		}
160		if s.Authzs == nil {
161			// 兼容旧版本写入的快照：授权表按需惰性建立。
162			s.Authzs = make(map[string]authzRec)
163		}
164		if s.NextAuthSeq < int64(len(s.AuthEvents)) {
165			return fmt.Errorf("%w: 授权变更序号不连续", ErrCorrupt)
166		}
167		return nil
168	}
169	
170	// store 负责一个登记册目录的加锁、读取与原子写入。
171	type store struct {
172		dir  string
173		lock *os.File // 跨进程 flock
174	}
175	
176	func dataFile(dir string) string { return filepath.Join(dir, "registry.json") }
177	func lockFile(dir string) string { return filepath.Join(dir, "registry.lock") }
178	func tempFile(dir string) string { return filepath.Join(dir, ".registry.json.tmp") }
179	
180	// acquireLock 在登记册目录中以非阻塞方式取独占 flock。
181	func acquireLock(dir string) (*os.File, error) {
182		f, err := os.OpenFile(lockFile(dir), os.O_CREATE|os.O_RDWR, fileMode)
183		if err != nil {
184			return nil, fmt.Errorf("registry: 无法打开锁文件: %w", err)
185		}
186		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
187			f.Close()
188			if errors.Is(err, syscall.EWOULDBLOCK) {
189				return nil, ErrLocked
190			}
191			return nil, fmt.Errorf("registry: 无法锁定登记册: %w", err)
192		}
193		return f, nil
194	}
195	
196	// load 读取快照。文件不存在时返回空快照；文件存在但无法读取或解析时
197	// 返回 ErrCorrupt，绝不静默当成空登记册。
198	func load(dir string) (*snapshot, error) {
199		b, err := os.ReadFile(dataFile(dir))
200		if err != nil {
201			if errors.Is(err, os.ErrNotExist) {
202				return newSnapshot(), nil
203			}
204			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
205		}
206		if len(b) == 0 {
207			return nil, fmt.Errorf("%w: 数据文件为空", ErrCorrupt)
208		}
209		var s snapshot
210		if err := json.Unmarshal(b, &s); err != nil {
211			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
212		}
213		if err := s.validate(); err != nil {
214			return nil, err
215		}
216		return &s, nil
217	}
218	
219	// save 以 temp 文件 + fsync + rename + 目录 fsync 的方式原子替换快照。
220	// 在持有全局锁时调用：写入与状态修改在同一临界区，进程被杀时要么
221	// 完整保留旧状态，要么完整呈现新状态。
222	func (st *store) save(s *snapshot) error {
223		b, err := json.MarshalIndent(s, "", "  ")
224		if err != nil {
225			return fmt.Errorf("registry: 序列化失败: %w", err)
226		}
227		tmp := tempFile(st.dir)
228		f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, fileMode)
229		if err != nil {
230			return fmt.Errorf("registry: 无法写入登记册: %w", err)
231		}
232		ok := false
233		defer func() {
234			if !ok {
235				f.Close()
236				os.Remove(tmp)
237			}
238		}()
239		if _, err := f.Write(b); err != nil {
240			return fmt.Errorf("registry: 写入失败: %w", err)
241		}
242		if err := f.Sync(); err != nil {
243			return fmt.Errorf("registry: 落盘失败: %w", err)
244		}
245		if err := f.Close(); err != nil {
246			return fmt.Errorf("registry: 关闭临时文件失败: %w", err)
247		}
248		if err := os.Rename(tmp, dataFile(st.dir)); err != nil {
249			return fmt.Errorf("registry: 替换数据文件失败: %w", err)
250		}
251		if dirFd, err := os.Open(st.dir); err == nil {
252			_ = dirFd.Sync()
253			dirFd.Close()
254		}
255		ok = true
256		return nil
257	}
258

