496		}); err != nil {
497			t.Fatal(err)
498		}
499		res, err := r.ProxyTransfer(preq)
500		if !errors.Is(err, ErrAuthorizationExpired) || !res.Replayed {
501			t.Fatalf("must replay first rejection: res=%+v err=%v", res, err)
502		}
503	}
