522	// ---- 并发：直接转让与代转争用同一版本 ----
523	
524	func TestConcurrentProxyVsDirectSameVersion(t *testing.T) {
525		r := mustCreate(t, tempDir(t))
526		authzWorld(t, r)
527		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
528			t.Fatal(err)
529		}
530		r.RegisterAccount("dave", "")
531	
532		const n = 16
533		var wg sync.WaitGroup
534		errs := make([]error, n)
535		wg.Add(n)
536		for i := 0; i < n; i++ {
537			i := i
538			go func() {
539				defer wg.Done()
540				if i%2 == 0 {
541					_, errs[i] = r.ProxyTransfer(proxyReq("bob", "a1", fmt.Sprintf("p%d", i)))
542				} else {
543					_, errs[i] = r.Transfer(xferReq("alice", "i1", "dave", 1, fmt.Sprintf("d%d", i)))
544				}
545			}()
546		}
547		wg.Wait()
548		succ := 0
549		for _, e := range errs {
550			if e == nil {
551				succ++
552			}
553		}
554		if succ != 1 {
555			t.Fatalf("exactly one of direct/proxy must succeed, got %d", succ)
556		}
557		h, _ := r.GetHolding("i1")
558		if h.Version != 2 {
559			t.Fatalf("version must be 2, got %d", h.Version)
560		}
561		hist, _ := r.History("i1")
562		if len(hist) != 2 {
563			t.Fatalf("exactly one transfer history, got %d", len(hist))
564		}
565		// 成功的若是代转，持有人必须是授权指定的 carol；若是直接转让，则是 dave
566		if hist[1].AuthID == "a1" && h.OwnerID != "carol" {
567			t.Fatalf("proxy winner must send to fixed receiver, got %s", h.OwnerID)
568		}
