571	// 撤销与代转同时发生：存在完整先后次序，撤销先则代转被拒，代转先则
572	// 授权已使用、撤销被拒。
573	func TestConcurrentRevokeVsProxy(t *testing.T) {
574		for range 20 {
575			r := mustCreate(t, filepath.Join(t.TempDir(), "d"))
576			authzWorld(t, r)
577			if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
578				t.Fatal(err)
579			}
580			var wg sync.WaitGroup
581			var proxyErr, revokeErr error
582			wg.Add(2)
583			go func() {
584				defer wg.Done()
585				_, proxyErr = r.ProxyTransfer(proxyReq("bob", "a1", "p1"))
586			}()
587			go func() {
588				defer wg.Done()
589				_, revokeErr = r.RevokeAuthorization(RevokeAuthorizationRequest{
590					Operator: "alice", Reason: "争用", RequestID: "rv1", AuthID: "a1",
591				})
592			}()
593			wg.Wait()
594			h, _ := r.GetHolding("i1")
595			a, _ := r.GetAuthorization("a1")
596			switch {
597			case proxyErr == nil:
598				if revokeErr == nil || !errors.Is(revokeErr, ErrAuthorizationUsed) {
599					t.Fatalf("proxy-first must make revoke fail with used, got %v", revokeErr)
600				}
601				if h.OwnerID != "carol" || h.Version != 2 || a.Status != AuthUsed {
602					t.Fatalf("proxy-first state wrong: %+v auth=%s", h, a.Status)
603				}
604			case errors.Is(proxyErr, ErrAuthorizationRevoked):
605				if revokeErr != nil {
606					t.Fatalf("revoke-first must succeed, got %v", revokeErr)
607				}
608				if h.OwnerID != "alice" || h.Version != 1 || a.Status != AuthRevoked {
609					t.Fatalf("revoke-first state wrong: %+v auth=%s", h, a.Status)
610				}
611			default:
612				t.Fatalf("unexpected ordering: proxy=%v revoke=%v", proxyErr, revokeErr)
613			}
614		}
615	}
