647				if !errors.Is(proxyErr, ErrAccountInactive) {
648					t.Fatalf("deactivate-first proxy must be inactive-rejected, got %v", proxyErr)
649				}
650				if h.OwnerID != "alice" || h.Version != 1 || len(hist) != 1 {
651					t.Fatalf("deactivate-first state wrong: %+v hist=%d", h, len(hist))
652				}
653			}
654		}
