708		req := createAuthReq(r, "a1", time.Hour)
709		req.ExpiresAt = base.Add(time.Hour)
710		if _, err := r.CreateAuthorization(req); err != nil {
711			t.Fatal(err)
712		}
713		// 到期前一刻可用
714		r.now = func() time.Time { return base.Add(time.Hour - time.Nanosecond) }
715		if a, _ := r.GetAuthorization("a1"); a.Status != AuthActive {
716			t.Fatalf("just before expiry must be active, got %s", a.Status)
717		}
718		// 正好到期时间点起不可使用
719		r.now = func() time.Time { return base.Add(time.Hour) }
720		if a, _ := r.GetAuthorization("a1"); a.Status != AuthExpired {
721			t.Fatalf("at expiry must be expired, got %s", a.Status)
722		}
723		if _, err := r.ProxyTransfer(proxyReq("bob", "a1", "p1")); !errors.Is(err, ErrAuthorizationExpired) {
724			t.Fatalf("proxy at expiry must fail expired, got %v", err)
725		}
