770			t.Fatalf("revoked auth must persist: %+v %v", a2, err)
771		}
772		evs, err := r2.AuthorizationHistory("i1")
773		if err != nil || len(evs) != 4 {
774			t.Fatalf("auth events must persist: %d %v", len(evs), err)
775		}
776		hist, err := r2.History("i1")
777		if err != nil || len(hist) != 2 || hist[1].AuthID != "a1" || hist[1].Operator != "bob" {
778			t.Fatalf("proxy history must persist with trustee and auth trace: %+v %v", hist, err)
779		}
