	want := map[string]int64{"bob": 100, "carol": 250}
	if len(tr.Payees) != 2 {
		t.Fatalf("payees wrong: %+v", tr.Payees)
	}
	for _, p := range tr.Payees {
		if want[p.Account] != p.Amount {
			t.Fatalf("payee %s amount wrong: %d", p.Account, p.Amount)
