	if _, err := r.Transfer(req2); err != nil {
		t.Fatalf("transfer with inactive payee must proceed: %v", err)
	}
	payables, _ = r.RoyaltyPayablesOf("bob")
	if len(payables) != 2 {
		t.Fatalf("inactive payee records must remain: %+v", payables)
	}
}

